/**
 * @description: User Portal Navbar (role-based, mirrors institute_portal Sidebar pattern)
 * @author: Institute User Portal
 * @date: 2026
 */
import React, { useContext } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { FaUserGraduate, FaUserTie, FaBus, FaUser, FaBookOpen } from 'react-icons/fa';
import { RiDashboardFill } from 'react-icons/ri';
import { AuthContext } from '../../App';
import { isExactMatch } from '../../services/commonUtills/FormValidations';

const getActiveNavModule = (pathname) => {
  if (!pathname || pathname === '/' || pathname.startsWith('/dashboard')) {
    return 'dashboard';
  }
  if (pathname.startsWith('/profile')) {
    return 'profile';
  }
  return null;
};

function NavbarUser({ onOpenHomework }) {
  const { stateAuth } = useContext(AuthContext);
  const location = useLocation();
  const navigate = useNavigate();
  const activeModule = getActiveNavModule(location.pathname);

  if (!stateAuth?.user) return null;

  const userType = (stateAuth.user.typ || '').toUpperCase();
  const codes = stateAuth.user.cds || '';

  const brandName =
    userType === 'STUDENT'
      ? 'Student Portal'
      : userType === 'TRANSPORT'
      ? 'Transport Portal'
      : 'Staff Portal';

  const roleTitle =
    userType === 'STUDENT'
      ? 'Student'
      : userType === 'TRANSPORT'
      ? 'Transport'
      : 'Staff';

  const roleIcon =
    userType === 'STUDENT' ? (
      <FaUserGraduate />
    ) : userType === 'TRANSPORT' ? (
      <FaBus />
    ) : (
      <FaUserTie />
    );

  return (
    <aside className="user-nav-sidebar">
      {/* Branding header */}
      <div className="user-nav-brand">
        <div className="user-nav-brand-icon">{roleIcon}</div>
        <div className="user-nav-brand-text">
          <h4>{brandName}</h4>
          <span>{stateAuth.user.emlid}</span>
        </div>
      </div>

      {/* Nav Links */}
      <div className="user-nav-menu-wrapper">
        <ul className="user-nav-menu-list">
          {/* Home / Dashboard */}
          {isExactMatch(codes, 'D_H_B') && (
            <li
              className={`user-nav-menu-item ${
                activeModule === 'dashboard' ? 'active' : ''
              }`}
            >
              <a
                href="/#"
                onClick={(e) => {
                  e.preventDefault();
                  navigate('/dashboard');
                }}
                className="user-nav-menu-link"
              >
                <RiDashboardFill className="menu-icon" />
                <span>Home</span>
              </a>
            </li>
          )}

          {/* Role section title */}
          <div className="user-nav-section">
            <span className="user-nav-section-title">{roleTitle}</span>

            {/* My Profile */}
            <li
              className={`user-nav-menu-item ${
                activeModule === 'profile' ? 'active' : ''
              }`}
            >
              <a
                href="/#"
                onClick={(e) => {
                  e.preventDefault();
                  navigate('/profile');
                }}
                className="user-nav-menu-link"
              >
                <FaUser className="menu-icon" />
                <span>My Profile</span>
              </a>
            </li>

            {/* Home Work */}
            <li className="user-nav-menu-item">
              <a
                href="/#"
                onClick={(e) => {
                  e.preventDefault();
                  onOpenHomework && onOpenHomework();
                }}
                className="user-nav-menu-link"
              >
                <FaBookOpen className="menu-icon" />
                <span>Home Work</span>
              </a>
            </li>
          </div>
        </ul>
      </div>
    </aside>
  );
}

export default NavbarUser;
